long long fact(int n) {
    if (n <= 1) return 1;        // base case
    return n * fact(n - 1);      // recursive case
}

void subseq(vector<int>& a, int i, vector<int>& cur, vector<vector<int>>& out) {
    if (i == (int)a.size()) { out.push_back(cur); return; }
    cur.push_back(a[i]);          // pick
    subseq(a, i + 1, cur, out);
    cur.pop_back();               // skip (backtrack)
    subseq(a, i + 1, cur, out);
}

long long power(long long x, long long n) {
    if (n == 0) return 1;
    long long half = power(x, n / 2);
    return (n % 2) ? half * half * x : half * half;
}

// Every recursion needs: a base case, a strictly smaller subproblem,
// and a way to combine. Draw the recursion tree before coding.
static int fib(int n, int[] memo) {
    if (n <= 1) return n;
    if (memo[n] != 0) return memo[n];
    return memo[n] = fib(n - 1, memo) + fib(n - 2, memo);
}

// Subsets: at each index, either take the element or don't.
static void subsets(int[] nums, int i, List<Integer> cur, List<List<Integer>> out) {
    if (i == nums.length) { out.add(new ArrayList<>(cur)); return; }
    subsets(nums, i + 1, cur, out);          // skip
    cur.add(nums[i]);
    subsets(nums, i + 1, cur, out);          // take
    cur.remove(cur.size() - 1);              // undo — this is the backtrack
}

/* C has no default recursion guard and stacks are typically 1-8 MB, so deep
   recursion segfaults rather than raising an error. Prefer iteration when the
   depth can reach 10^5. */
long long fib(int n, long long *memo) {
    if (n <= 1) return n;
    if (memo[n]) return memo[n];
    return memo[n] = fib(n - 1, memo) + fib(n - 2, memo);
}

/* Subsets: at each index, take the element or don't. The caller owns the
   buffers — there is no container to return. */
void subsets(const int *nums, int n, int i, int *cur, int curLen,
             void (*emit)(const int *, int)) {
    if (i == n) { emit(cur, curLen); return; }
    subsets(nums, n, i + 1, cur, curLen, emit);           /* skip */
    cur[curLen] = nums[i];
    subsets(nums, n, i + 1, cur, curLen + 1, emit);       /* take */
    /* nothing to undo: curLen is passed by value, which IS the backtrack */
}

/* Tail-recursive shapes are often clearer as loops in C — the compiler may
   or may not eliminate the call. */
int gcd(int a, int b) { while (b) { int t = a % b; a = b; b = t; } return a; }

// Go grows goroutine stacks dynamically, so deep recursion is far safer here
// than in Python or C — but it is still not free.
func fib(n int, memo map[int]int) int {
	if n <= 1 {
		return n
	}
	if v, ok := memo[n]; ok {
		return v
	}
	memo[n] = fib(n-1, memo) + fib(n-2, memo)
	return memo[n]
}

// Subsets: at each index, take the element or don't.
func subsets(nums []int) [][]int {
	var out [][]int
	var cur []int

	var go_ func(i int)
	go_ = func(i int) {
		if i == len(nums) {
			// MUST copy: cur's backing array is reused as we backtrack.
			out = append(out, append([]int(nil), cur...))
			return
		}
		go_(i + 1) // skip
		cur = append(cur, nums[i])
		go_(i + 1) // take
		cur = cur[:len(cur)-1]
	}
	go_(0)
	return out
}
